package com.enterprisehub.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="service_requests") public class ServiceRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String title; @Column(nullable=false,columnDefinition="TEXT") public String description; @Column(nullable=false) public String category; @Column(nullable=false) public String priority; @Column(nullable=false) public String status; @Column(nullable=false) public String impact="MEDIUM"; @Column(nullable=false) public String urgency="MEDIUM"; @Column(name="priority_reason",nullable=false) public String priorityReason; @Column(name="sla_due_at") public Instant slaDueAt; @Column(name="resolved_at") public Instant resolvedAt; @Column(name="resolution_seconds") public Long resolutionSeconds; @Column(name="resolved_on_time") public Boolean resolvedOnTime; @ManyToOne @JoinColumn(name="requester_id",nullable=false) public Employee requester; @ManyToOne @JoinColumn(name="assignee_id") public Employee assignee; @ManyToOne @JoinColumn(name="department_id",nullable=false) public Department department; @Column(name="due_at") public Instant dueAt; @Column(name="idempotency_key",unique=true,length=180) public String idempotencyKey; @Column(name="created_at",insertable=false,updatable=false) public Instant createdAt; @Column(name="updated_at",insertable=false,updatable=false) public Instant updatedAt; @Version public long version; @Transient public String slaStatus; @Transient public Long slaRemainingSeconds; public ServiceRequest(){} }
